<?php require '../config/database.php'; require_once '../config/auth.php'; require_role('user'); $uid=$_SESSION['user_id']; $member_id=mysqli_fetch_assoc(mysqli_query($conn,"SELECT id FROM members WHERE user_id=$uid"))['id']; if(isset($_GET['book'])){ $cid=(int)$_GET['book']; mysqli_query($conn,"INSERT INTO class_bookings(class_id,member_id) VALUES($cid,$member_id)"); header('Location: classes.php'); exit; } $classes=mysqli_query($conn,"SELECT c.*,u.full_name trainer FROM classes c LEFT JOIN trainers t ON c.trainer_id=t.id LEFT JOIN users u ON t.user_id=u.id ORDER BY schedule_datetime"); ?>
<!DOCTYPE html><html><head><title>Classes</title><link rel="stylesheet" href="../assets/css/style.css"><script src="../assets/js/app.js"></script></head><body><div class="layout"><?php include '_nav.php'; ?><main class="main"><h1>Online Fitness Class Booking</h1><div class="grid" style="padding:0"><?php $n=1; while($r=mysqli_fetch_assoc($classes)):?><div class="card"><h2><?=e($r['title'])?></h2><p><span class="badge"><?=e($r['class_type'])?></span></p><p>Trainer: <?=e($r['trainer'])?><br>Schedule: <?=$r['schedule_datetime']?><br>Capacity: <?=$r['capacity']?></p><?php if($r['stream_link']):?><div class="player"><iframe width="100%" height="100%" src="<?=e($r['stream_link'])?>" frameborder="0" allowfullscreen></iframe></div><?php endif;?><p>Live class countdown: <b id="timer<?=$n?>">30:00</b></p><button onclick="startTimer(1800,'timer<?=$n?>')">Start Workout Timer</button> <a class="btn orange" href="?book=<?=$r['id']?>">Book Class</a></div><?php $n++; endwhile;?></div></main></div></body></html>
